#include <Arduino.h>
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ILI9341.h>

Adafruit_ILI9341 display(10, 9);
String pending;
unsigned long lastByteMs = 0;

void showMessage() {
  display.fillScreen(ILI9341_BLACK);
  display.setCursor(0, 0);
  display.setTextColor(ILI9341_WHITE);
  display.setTextSize(2);
  display.print(pending);
  Serial.println(pending);
  pending = "";
}

void setup() {
  display.begin();
  display.setRotation(1);
  Serial.begin(9600);
}

void loop() {
  while (Serial.available() > 0) {
    char c = (char)Serial.read();
    lastByteMs = millis();
    if (c == '\n') {
      if (pending.endsWith("\r")) pending.remove(pending.length() - 1);
      showMessage();
    } else {
      pending += c;
    }
  }
  if (pending.length() > 0 && (unsigned long)(millis() - lastByteMs) >= 20) {
    showMessage();
  }
}
